:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #eaeaea;
  --muted: #8a8fa3;
  --grid: #0f3460;
}

* {
  box-sizing: border-box;
}

[hidden] {
  display: none !important;
}

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 16px;
}

.card {
  background: var(--card);
  border-radius: 16px;
  padding: 24px;
  width: 100%;
  max-width: 480px;
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.5);
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
}

h1 {
  margin: 0;
  font-size: 1.5rem;
  letter-spacing: 1px;
}

.score {
  margin: 0;
  font-size: 1.125rem;
  color: var(--accent);
  font-weight: 700;
}

.board-wrap {
  position: relative;
  width: 100%;
  aspect-ratio: 1 / 1;
  background: var(--grid);
  border-radius: 8px;
  overflow: hidden;
}

canvas {
  display: block;
  width: 100%;
  height: 100%;
  image-rendering: pixelated;
}

.overlay {
  position: absolute;
  inset: 0;
  background: rgba(22, 33, 62, 0.94);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 20px;
  gap: 12px;
}

.overlay h2 {
  margin: 0;
  font-size: 1.25rem;
  color: var(--accent);
}

.overlay p {
  margin: 0;
  color: var(--text);
  line-height: 1.5;
  max-width: 34ch;
}

.controls {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}

.btn {
  flex: 1 1 auto;
  min-width: 120px;
  padding: 12px 20px;
  font-size: 1rem;
  font-family: inherit;
  font-weight: 600;
  color: var(--text);
  background: var(--grid);
  border: 2px solid var(--accent);
  border-radius: 8px;
  cursor: pointer;
  transition: background 0.15s, transform 0.05s;
}

.btn:hover {
  background: var(--accent);
  color: var(--bg);
}

.btn:focus-visible {
  outline: 3px solid var(--text);
  outline-offset: 2px;
}

.btn:active {
  transform: scale(0.97);
}

.btn.primary {
  background: var(--accent);
  color: var(--bg);
}

.btn.primary:hover {
  background: var(--text);
  border-color: var(--text);
}

.hint {
  margin: 0;
  font-size: 0.9375rem;
  color: var(--muted);
  text-align: center;
}

kbd {
  background: var(--grid);
  border-radius: 4px;
  padding: 2px 6px;
  font-family: inherit;
  font-size: 0.875rem;
}

@media (max-width: 400px) {
  .card {
    padding: 16px;
  }
  h1 {
    font-size: 1.25rem;
  }
  .btn {
    min-width: 100px;
    padding: 10px 14px;
  }
}

(function () {
  "use strict";

  const canvas = document.getElementById("board");
  const ctx = canvas.getContext("2d");
  const scoreEl = document.getElementById("score");
  const overlay = document.getElementById("overlay");
  const overlayTitle = document.getElementById("overlay-title");
  const overlayText = document.getElementById("overlay-text");
  const overlayBtn = document.getElementById("overlay-btn");
  const pauseBtn = document.getElementById("pause-btn");
  const restartBtn = document.getElementById("restart-btn");

  const GRID = 20;
  const CELL = canvas.width / GRID;
  const TICK_MS = 130;
  const COLORS = {
    bg: "#0f3460",
    snake: "#e94560",
    head: "#eaeaea",
    food: "#e94560"
  };

  let snake, dir, nextDir, food, score, running, paused, over, timer;

  function reset() {
    snake = [{ x: 10, y: 10 }];
    dir = { x: 1, y: 0 };
    nextDir = { x: 1, y: 0 };
    score = 0;
    over = false;
    running = false;
    paused = true;
    placeFood();
    updateScore();
    draw();
    setPauseButton();
    clearInterval(timer);
    timer = null;
  }

  function placeFood() {
    do {
      food = {
        x: Math.floor(Math.random() * GRID),
        y: Math.floor(Math.random() * GRID)
      };
    } while (snake.some(function (s) { return s.x === food.x && s.y === food.y; }));
  }

  function updateScore() {
    scoreEl.textContent = String(score);
  }

  function setPauseButton() {
    pauseBtn.textContent = paused ? "Resume" : "Pause";
    pauseBtn.setAttribute("aria-pressed", String(paused));
  }

  function start() {
    if (over) reset();
    if (running) return;
    running = true;
    paused = false;
    overlay.hidden = true;
    setPauseButton();
    clearInterval(timer);
    timer = setInterval(step, TICK_MS);
  }

  function togglePause() {
    if (over) return;
    if (!running) {
      start();
      return;
    }
    paused = !paused;
    setPauseButton();
    if (paused) {
      clearInterval(timer);
      timer = null;
    } else {
      timer = setInterval(step, TICK_MS);
    }
  }

  function step() {
    if (paused || over) return;
    dir = nextDir;
    const head = { x: snake[0].x + dir.x, y: snake[0].y + dir.y };

    if (
      head.x < 0 || head.x >= GRID ||
      head.y < 0 || head.y >= GRID ||
      snake.some(function (s) { return s.x === head.x && s.y === head.y; })
    ) {
      gameOver();
      return;
    }

    snake.unshift(head);
    if (head.x === food.x && head.y === food.y) {
      score += 10;
      updateScore();
      placeFood();
    } else {
      snake.pop();
    }
    draw();
  }

  function gameOver() {
    over = true;
    running = false;
    paused = true;
    clearInterval(timer);
    timer = null;
    setPauseButton();
    overlayTitle.textContent = "Game Over";
    overlayText.textContent = "Final score: " + score + ". Hit the walls or yourself? Try again!";
    overlayBtn.textContent = "Play again";
    overlay.hidden = false;
    overlayBtn.focus();
  }

  function draw() {
    ctx.fillStyle = COLORS.bg;
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.fillStyle = COLORS.food;
    ctx.fillRect(food.x * CELL + 2, food.y * CELL + 2, CELL - 4, CELL - 4);

    snake.forEach(function (seg, i) {
      ctx.fillStyle = i === 0 ? COLORS.head : COLORS.snake;
      ctx.fillRect(seg.x * CELL + 1, seg.y * CELL + 1, CELL - 2, CELL - 2);
    });
  }

  function onKey(e) {
    const key = e.key;
    if (key === "p" || key === "P") {
      e.preventDefault();
      togglePause();
      return;
    }
    if (key === "r" || key === "R") {
      e.preventDefault();
      reset();
      overlayTitle.textContent = "How to play";
      overlayText.textContent = "Use the arrow keys to move the snake. Eat the food to grow and score points. Don't hit the walls or yourself!";
      overlayBtn.textContent = "Start game";
      overlay.hidden = false;
      return;
    }

    const map = {
      ArrowUp: { x: 0, y: -1 },
      ArrowDown: { x: 0, y: 1 },
      ArrowLeft: { x: -1, y: 0 },
      ArrowRight: { x: 1, y: 0 }
    };
    const nd = map[key];
    if (!nd) return;
    e.preventDefault();
    if (!running || paused || over) return;
    if (nd.x === -dir.x && nd.y === -dir.y) return;
    nextDir = nd;
  }

  overlayBtn.addEventListener("click", start);
  pauseBtn.addEventListener("click", togglePause);
  restartBtn.addEventListener("click", function () {
    reset();
    overlayTitle.textContent = "How to play";
    overlayText.textContent = "Use the arrow keys to move the snake. Eat the food to grow and score points. Don't hit the walls or yourself!";
    overlayBtn.textContent = "Start game";
    overlay.hidden = false;
    overlayBtn.focus();
  });
  document.addEventListener("keydown", onKey);

  reset();
  overlay.hidden = false;
  overlayTitle.textContent = "How to play";
  overlayText.textContent = "Use the arrow keys to move the snake. Eat the food to grow and score points. Don't hit the walls or yourself!";
  overlayBtn.textContent = "Start game";
})();
